listen:[["Un biglietto di andata e ritorno per Milano, seconda classe.","Eine Hin- und Rückfahrkarte nach Mailand, zweite Klasse."],["Il treno parte dal binario sei.","Der Zug fährt von Gleis sechs."],["Vorrei prenotare una camera singola per tre notti.","Ich möchte ein Einzelzimmer für drei Nächte reservieren."],["La colazione è dalle sette alle dieci.","Frühstück gibt es von 7 bis 10 Uhr."],["Abito al terzo piano, senza ascensore.","Ich wohne im dritten Stock, ohne Aufzug."],["Prenda la seconda a sinistra.","Nehmen Sie die zweite links."],["Il treno ha venti minuti di ritardo.","Der Zug hat 20 Minuten Verspätung."]],
